package models

import "time"

// TxDetails is everything the details drawer of a transaction shows.
type TxDetails struct {
	Tx *Transaction
	// ReceiptScan tells receipts can be scanned (reading them is on).
	ReceiptScan bool
	// SMS is the message the transaction was created from, if any, and
	// SMSTemplate the name of the template that read it.
	SMS         *SMSMessage
	SMSTemplate string
	// Recurrent is the recurrent transaction it was generated by, and
	// RecurrentTxs its other occurrences, newest first.
	Recurrent    *RecurrentTx
	RecurrentTxs []Transaction
	// Reimburses is the expense this income pays back.
	Reimburses *Transaction
	// Pair is the other side of the transfer pair it's a side of.
	Pair *Transaction
	// CounterpartyTxs are the latest other transactions with its
	// counterparty, and CounterpartyMonth all of them in Month.
	CounterpartyTxs   []Transaction
	CounterpartyMonth *TxSummary
	// Budget is its category's spending of Month, against its budget if any.
	Budget *BudgetSummaryItem
	// Month is the 1st of the month Period is named after.
	Month time.Time
	// Period is the user's month of the transaction, the stats are of.
	Period Period
}
